import { animateIosApp } from './app-motion.mjs';
import { CREDIT } from '../game/credits.mjs';
import { PHONE_HELP_ACKNOWLEDGEMENTS } from './help-content.mjs';
import { createUserPhotoLibrary } from './user-photos.mjs';
import { PHONE_ORIENTATION_STYLE } from './orientation-style.mjs';
import { fitPhone } from './layout.mjs';
import { installSerialMotion, waitMotion } from '../ui/serial-motion.mjs';
import { mountIosPhotos } from './photos.mjs';
import { mountMusic } from './music.mjs';
import { createMusicSession } from './music-session.mjs';
import { mountMusicIsland,DYNAMIC_ISLAND_STYLE } from './dynamic-island.mjs';
import { patchHtml } from './dom-patch.mjs';
import { mountHypnosisApp } from './hypnosis-app.mjs';
import { PHONE_STYLE } from './style.mjs';
import { PHONE_NATIVE_STYLE } from './native-style.mjs';
import { PHONE_APPS, phoneIcon, appIcon } from './icons.mjs';

const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photoUrl=value=>/^(?:https?:|blob:|\/|data:image\/(?:png|jpeg|webp|gif);)/.test(String(value??''))?escape(value):'';
const present=snapshot=>(snapshot.people??[]).filter(x=>x.present);
function dateParts(snapshot){const value=String(snapshot.date??''),match=value.match(/(?:(\d{4})[年/-])?(\d{1,2})[月/-](\d{1,2})/);const year=Number(match?.[1]??snapshot.year??2026),month=Number(match?.[2]??10),day=Number(match?.[3]??12),date=new Date(Date.UTC(year,month-1,day));return{year,month,day,weekday:['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][date.getUTCDay()],first:new Date(Date.UTC(year,month-1,1)).getUTCDay(),days:new Date(Date.UTC(year,month,0)).getUTCDate()};}
function portrait(person){return person?.photo?`<img alt="${escape(person.name)}" src="${photoUrl(person.photo)}">`:`<span>${escape(person?.name?.slice(-1)??'人')}</span>`;}

export async function mountIphone16Phone(container,{getSnapshot,stageHypnosis,getPhotos=null,openApp=null,onHome=()=>{},onOrientation=()=>{}}){
 const doc=container.ownerDocument,win=doc.defaultView,root=doc.createElement('section');const motion=installSerialMotion(doc);root.className='phone16-root';root.setAttribute('aria-label','HypnoOS 新手机');
 const style=doc.createElement('style');style.textContent=PHONE_STYLE+PHONE_ORIENTATION_STYLE+PHONE_NATIVE_STYLE+DYNAMIC_ISLAND_STYLE;root.append(style);
 const device=doc.createElement('div');device.className='ip-device';device.innerHTML=`<div class="ip-screen" data-view="home"><div class="ip-wallpaper"></div><div class="ip-status"><span data-phone-time>10:40</span><span class="ip-status-icons">${phoneIcon('signal')}${phoneIcon('wifi')}${phoneIcon('battery')}</span></div><div class="ip-island" data-hardware="camera" aria-hidden="true"><i class="ip-island-dot" hidden></i><span></span><i class="ip-camera-dot"></i></div><main class="ip-content"></main><button class="ip-home-indicator" aria-label="返回手机主屏幕"></button><div class="ip-toast" role="status"></div></div>`;root.append(device);const orientationButton=doc.createElement('button');orientationButton.className='ip-orientation-toggle';orientationButton.type='button';orientationButton.textContent='横屏';orientationButton.setAttribute('aria-label','切换手机为横屏');const globalControls=doc.createElement('div');globalControls.className='ip-global-controls';const homeButton=doc.createElement('button');homeButton.type='button';homeButton.textContent='回首页';homeButton.setAttribute('aria-label','回首页');homeButton.addEventListener('click',()=>go('home'));globalControls.append(orientationButton,homeButton);root.append(globalControls);container.append(root);root.dataset.orientation='portrait';
 const screen=root.querySelector('.ip-screen'),content=root.querySelector('.ip-content'),toast=root.querySelector('.ip-toast');
 let hypnosisView=null,photosView=null,musicView=null,musicSession=null;const musicCache=new Map();const photoCache=new Map();const userPhotos=createUserPhotoLibrary(doc.defaultView); const hypnosisDraftCache=new Map();
 let snapshot={people:[],locations:[],location:null,time:'',date:'',energy:0,vipRank:0,history:[]},route='home',appId='',search='',destroyed=false,refreshEpoch=0,toastTimer=0;
 let appChanging=false;
 let draft={scope:'personal',detailId:''},orientation='portrait',orientationAnimation=null;
 const musicIsland=mountMusicIsland(root.querySelector('.ip-island'),{onOpen:async()=>{musicCache.set('music-tab','now');await go('music','music');musicView?.openNowPlaying();},onPause:()=>musicSession?.pause(),onNext:()=>musicSession?.step(1)});
 const fit=()=>{const frame=fitPhone({width:container.clientWidth,height:Math.max(0,container.clientHeight-(root.dataset.controlsDocked==='true'?0:38))},orientation);device.style.width=frame.width+'px';device.style.height=frame.height+'px';screen.style.width=frame.screenWidth+'px';screen.style.height=frame.screenHeight+'px';device.style.transform=`scale(${frame.scale})`;root.dataset.scale=String(frame.scale);};
 async function rotateTo(value){if(!['portrait','landscape'].includes(value))throw Error('未知手机方向');if(destroyed||orientation===value)return;const oldScale=Number(root.dataset.scale)||1,reduced=win.matchMedia?.('(prefers-reduced-motion: reduce)').matches;orientation=value;root.dataset.orientation=value;orientationButton.textContent=value==='portrait'?'横屏':'竖屏';orientationButton.setAttribute('aria-label',value==='portrait'?'切换手机为横屏':'切换手机为竖屏');const external=onOrientation(value,{animate:!reduced});root.dispatchEvent(new win.CustomEvent('hypno:phone-orientation',{bubbles:true,detail:{orientation:value}}));fit();root.dataset.rotating='true';try{if(external?.then)await external;else if(!reduced&&device.animate){root.style.overflow='visible';orientationAnimation=device.animate([{transform:`rotate(${value==='landscape'?90:-90}deg) scale(${oldScale})`},{transform:`rotate(0deg) scale(${root.dataset.scale})`}],{duration:480,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});await waitMotion(orientationAnimation);orientationAnimation.cancel();}}finally{orientationAnimation=null;root.style.overflow='';delete root.dataset.rotating;}}
 const setOrientation=value=>motion.run(()=>rotateTo(value));
 const toggleOrientation=()=>motion.run(()=>rotateTo(orientation==='portrait'?'landscape':'portrait'));
 const screenOrientation=()=>{void setOrientation(win.matchMedia('(orientation: landscape)').matches?'landscape':'portrait');};win.addEventListener('orientationchange',screenOrientation);orientationButton.addEventListener('click',()=>{void toggleOrientation();});
 function notify(message){toast.textContent=message;win.clearTimeout(toastTimer);toastTimer=win.setTimeout(()=>{toast.textContent='';},3800);}


 function leaveMusic(){musicView?.destroy();musicView=null;}
 const resolveMusicFile=file=>/^(?:https?:|blob:|data:|\/)/.test(file)?file:(snapshot.assetBase??win.__ST_GAME_ASSET_BASE__??'/public/frontends/hypnosis-app/assets/').replace(/\/?$/,'/')+file;
 function ensureMusicSession(){return musicSession??=createMusicSession({resolveFile:resolveMusicFile,cache:musicCache,audioFactory:()=>doc.createElement('audio'),urlApi:win.URL,win,onPlayback:(state,track)=>{if(!destroyed)musicIsland.update(state,track);}});}
 function home(){const date=dateParts(snapshot),people=present(snapshot);return `<section class="ip-home"><div class="ip-widgets"><button class="ip-widget ip-date-widget" data-open="calendar" aria-label="查看今天的日期"><small>${date.weekday}</small><div class="ip-widget-orb"></div><h2>${date.month}月${date.day}日</h2><p>${date.year}年 ${phoneIcon('calendar')}</p></button><button class="ip-widget people" data-scope="personal"><small>此刻与你同在</small><strong>${people.length}<span style="font-size:12px;font-weight:450;margin-left:4px">人</span></strong><p>${escape(snapshot.location?.name??'当前地点')}</p><div class="ip-mini-faces">${people.slice(0,3).map(p=>p.photo?`<img alt="${escape(p.name)}" src="${photoUrl(p.photo)}">`:`<i>${escape(p.name.slice(-1))}</i>`).join('')}</div></button></div><div class="ip-app-grid">${PHONE_APPS.filter(x=>!x.dock).map(app=>`<button class="ip-app" data-open="${app.id}" aria-label="打开${app.name}">${appIcon({...app,day:date.day,dayLabel:date.weekday})}<span>${app.name}</span></button>`).join('')}</div><div class="ip-home-bottom"><button class="ip-home-search" data-action="search">${phoneIcon('search')}搜索</button><nav class="ip-dock" aria-label="常用应用">${PHONE_APPS.filter(x=>x.dock).map(app=>`<button class="ip-app" data-open="${app.id}" aria-label="打开${app.name}">${appIcon(app)}<span>${app.name}</span></button>`).join('')}</nav></div></section>`;}
 function appSearch(){const apps=PHONE_APPS.filter(x=>!search||x.name.includes(search));return `<section class="ip-app-page"><div class="ip-scroll"><h1 class="ip-title">搜索</h1><label class="ip-search">${phoneIcon('search')}<input data-bind="search" aria-label="搜索应用" placeholder="搜索应用" value="${escape(search)}"></label>${apps.map(app=>`<button class="ip-simple-row" data-open="${app.id}" style="width:100%;border:0;background:none;text-align:left">${appIcon(app)}<span>${app.name}</span>${phoneIcon('chevron')}</button>`).join('')}</div></section>`;}


 function simple(){const app=PHONE_APPS.find(x=>x.id===appId)??{name:'应用'},date=dateParts(snapshot);let body='';
  if(appId==='clock'){const [hours,minutes]=String(snapshot.time??'10:40').split(':').map(Number);body=`<div class="ip-clock-face"><span class="ip-clock-digit" style="left:calc(50% - 8px);top:12px">12</span><span class="ip-clock-digit" style="right:15px;top:calc(50% - 8px)">3</span><span class="ip-clock-digit" style="bottom:12px;left:calc(50% - 5px)">6</span><span class="ip-clock-digit" style="left:15px;top:calc(50% - 8px)">9</span><i class="ip-clock-hand hour" style="transform:rotate(${hours%12*30+minutes*.5}deg)"></i><i class="ip-clock-hand" style="transform:rotate(${minutes*6}deg)"></i></div><h2 style="text-align:center;font-size:37px;font-weight:350;color:#8e749f">${escape(snapshot.time)}</h2><p class="ip-subtitle" style="text-align:center">${escape(snapshot.location?.name)}</p>`;}
  else if(appId==='calendar'){body=`<h2 style="font-size:24px;font-weight:450;color:#9d82ac;margin-top:30px">${date.year} 年 ${date.month} 月</h2><div class="ip-calendar-grid">${['日','一','二','三','四','五','六'].map(x=>`<span style="font-size:10px;color:#beacc8">${x}</span>`).join('')}${Array(date.first).fill('<span></span>').join('')}${Array.from({length:date.days},(_,i)=>`<span class="${i+1===date.day?'today':''}">${i+1}</span>`).join('')}</div><div class="ip-context-chip">${phoneIcon('location')}${escape(snapshot.location?.name??'当前地点')} · ${escape(snapshot.time)}</div>`;}
  else if(appId==='help'){body='<div class="ip-summary">个人催眠可复选在场人物，逐人计费与结算。<br>地点催眠包含封闭与开放空间，均为临时生效。<br>抵抗突破后仍需独立剧情判定。<br><br>操作写入日程，读完对话后推进。消息按当前聊天保存；给联系人发消息同样会加入日程。</div><h2 style="margin:28px 0 12px;font-size:19px;font-weight:600">感谢与署名</h2>'+PHONE_HELP_ACKNOWLEDGEMENTS.map(item=>`<section style="padding:12px 0;border-bottom:1px solid #dcd3e3"><strong style="font-size:12px;color:#9573a1">${escape(item.title)}</strong><p style="font-size:12px;line-height:1.9;color:#786581;overflow-wrap:anywhere">${escape(item.text)}</p></section>`).join('');}
  else if(appId==='settings'){body=`<div class="ip-simple-row">${phoneIcon('moon')}<span>外观</span><small>暮紫</small></div><button class="ip-simple-row" data-action="legacy" style="width:100%;background:none;border-left:0;border-right:0;border-top:0">${phoneIcon('settings')}<span>聊天与模型设置</span>${phoneIcon('chevron')}</button><div class="ip-simple-row">${phoneIcon('hypnosis')}<span>HypnoOS</span><small>完全免费</small></div><a class="ip-simple-row" href="${escape(new URL('../pet-resources.zip',new URL(snapshot.assetBase??win.__ST_GAME_ASSET_BASE__??'/public/frontends/hypnosis-app/assets/',doc.baseURI)).href)}" download="桌宠本地资源包.zip" style="color:inherit;text-decoration:none">${phoneIcon('inventory')}<span>下载桌宠资源包</span>${phoneIcon('chevron')}</a><p class="ip-subtitle" style="margin:12px 0;line-height:1.8">可选的本地图片包。解压到酒馆当前用户的 user/files 目录，重载聊天后生效。未安装或文件不完整时继续使用 CDN。</p>`;}
  else body=`<button class="ip-primary" data-action="legacy">打开${escape(app.name)}${phoneIcon('chevron')}</button>`;
  return `<section class="ip-app-page"><div class="ip-scroll"><p class="ip-kicker">HYPNOOS</p><h1 class="ip-title">${escape(app.name)}</h1><p class="ip-subtitle">${appId==='photos'?'保留下来的每一个瞬间。':appId==='clock'||appId==='calendar'?'当前故事时间':''}</p>${body||'<div class="ip-empty">暂无记录</div>'}<p class="ip-subtitle">${CREDIT}</p></div></section>`;
 }

 function render(){if(destroyed)return;screen.scrollTop=0;root.scrollTop=0;content.scrollTop=0;screen.dataset.view=route==='home'?'home':'hypnosis';screen.dataset.theme=route==='hypnosis'?'hypnosis':'default';root.dataset.route=route;root.dataset.appId=appId;root.dataset.scope=draft.scope;root.querySelector('[data-phone-time]').textContent=snapshot.time||'—';
  if(route==='music'){screen.dataset.theme='music';photosView?.destroy();photosView=null;hypnosisView?.destroy();hypnosisView=null;if(!musicView){content.replaceChildren();musicView=mountMusic(content,{resolveFile:resolveMusicFile,cache:musicCache,notify,session:ensureMusicSession()});}else musicView.refresh();return;}
  leaveMusic();
  if(route==='photos'){hypnosisView?.destroy();hypnosisView=null;if(!photosView){content.replaceChildren();photosView=mountIosPhotos(content,{getLibrary:()=>userPhotos.list(),importFiles:files=>userPhotos.importFiles(files),deletePhoto:id=>userPhotos.remove(id),onHome:()=>go('home'),notify,cache:photoCache});}return;}
  photosView?.destroy();photosView=null;
  if(route==='hypnosis'){if(!hypnosisView){content.innerHTML='';hypnosisView=mountHypnosisApp(content,{getSnapshot,stageHypnosis,onHome:()=>go('home'),notify,initialScope:draft.scope,draftCache:hypnosisDraftCache});}return;}
  hypnosisView?.destroy();hypnosisView=null;
  if(route==='legacy'){content.innerHTML='<section class="ip-app-page"><div class="ip-legacy-slot"></div></section>';return;}
  patchHtml(content,route==='home'?home():route==='app-search'?appSearch():simple());

 }
 async function refresh(){const token=++refreshEpoch;try{const next=await getSnapshot();if(destroyed||token!==refreshEpoch)return;const changed=JSON.stringify(snapshot)!==JSON.stringify(next);snapshot=next;if(changed&&!appChanging&&route!=='legacy'){if(route==='hypnosis'&&hypnosisView)await hypnosisView.refresh();else if(route==='photos'&&photosView)await photosView.refresh();else render();}}catch(error){notify(error.message);}}
 const appOrigins=new Map();
 function iconRect(id){const button=[...content.querySelectorAll('[data-open]')].find(node=>node.dataset.open===id&&(!appOrigins.get(id)||node.classList.contains(appOrigins.get(id))));return (button?.querySelector('.ip-app-icon')??button)?.getBoundingClientRect();}
 function go(next,id=appId,source=null){return motion.run(async()=>{if(destroyed||(next===route&&id===appId))return;const previous=route,previousApp=appId,origin=(source?.querySelector('.ip-app-icon')??source)?.getBoundingClientRect()??iconRect(id),kind=next==='home'?'close':previous==='home'||previous==='app-search'?'open':'push';appChanging=true;try{await animateIosApp(content,{kind,origin:kind==='close'?()=>iconRect(previousApp):origin,render(){if(previous==='legacy'){onHome();win.__ST_IPHONE16_LEGACY_ROOT__=null;}appId=id;route=next;if(next==='home')search='';render();}});}finally{appChanging=false;}});}
 async function launch(id,source=null){if(source)appOrigins.set(id,source.classList.contains('ip-widget')?'ip-widget':'ip-app');if(!PHONE_APPS.some(x=>x.id===id))return;if(['hypnosis','photos','music'].includes(id)){await go(id,id,source);return;}if(['clock','calendar','help','settings'].includes(id)){await go('simple',id,source);return;}await legacy(id,source);}
 async function legacy(id=appId,source=null){if(!openApp){notify('此应用尚未连接');return;}await go('legacy',id,source);if(destroyed||route!=='legacy'||appId!==id)return;try{await openApp(id,content.querySelector('.ip-legacy-slot'));}catch(error){if(!destroyed){route='simple';render();notify(error.message);}}}
 root.addEventListener('click',async event=>{const button=event.target.closest('[data-open],[data-route],[data-scope],[data-action],[data-detail]');if(!button||button.disabled)return;
  if(button.dataset.open){await launch(button.dataset.open,button);return;}if(button.dataset.route){go(button.dataset.route);return;}if(button.dataset.scope){draft={...draft,scope:button.dataset.scope};search='';go('hypnosis','hypnosis',button);return;}
  if(button.dataset.action==='search'){search='';go('app-search');return;}
  if(button.dataset.action==='legacy'){await legacy();return;}
 });
 root.addEventListener('input',event=>{if(event.target.dataset.bind==='search'){search=event.target.value;render();}});
 root.querySelector('.ip-home-indicator').addEventListener('click',()=>go('home'));win.addEventListener('resize',fit);fit();render();await refresh();
 const timer=win.setInterval(refresh,5000);return{root,refresh,resize:fit,setOrientation,toggleOrientation,get orientation(){return orientation;},setControlsDocked(value){root.dataset.controlsDocked=String(Boolean(value));fit();},pauseMedia:()=>musicSession?.pause(),home:()=>go('home'),openApp:launch,openHypnosis:()=>go('hypnosis','hypnosis'),destroy(){orientationAnimation?.cancel();leaveMusic();musicSession?.destroy();musicSession=null;musicIsland.destroy();photosView?.destroy();hypnosisView?.destroy();destroyed=true;refreshEpoch++;win.clearInterval(timer);win.clearTimeout(toastTimer);win.removeEventListener('resize',fit);win.removeEventListener('orientationchange',screenOrientation);root.remove();}};
}
